DELETE FROM projects;
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
    case_study_problem_en, case_study_problem_ar, case_study_solution_en, case_study_solution_ar,
    case_study_outcome_en, case_study_outcome_ar, case_study_role_en, case_study_role_ar,
    case_study_stack_en, case_study_stack_ar, case_study_steps_en, case_study_steps_ar,
    faqs,
    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    1, 'project-1', 'published', true,
    'Mini Shop – Single Page Store', 'Mini Shop – متجر صفحة واحدة',
    'Single-page Arabic storefront with cart and checkout, built in pure HTML, CSS, and JavaScript.', 'متجر صفحة واحدة باللغة العربية مع سلة شراء وخطوة دفع، مبني بالكامل باستخدام HTML وCSS وJavaScript.',
    'Mini Shop – Single Page Store is a lightweight demo shop built with HTML, CSS, and vanilla JavaScript. The page combines a simple hero, product grid, cart, and checkout section into one scrolling experience to showcase basic front-end e-commerce UX in Arabic.', 'Mini Shop – Single Page Store هو مشروع متجر إلكتروني خفيف مبني باستخدام HTML وCSS وJavaScript بدون أي إطار عمل. تجمع الصفحة بين قسم تعريفي بسيط وشبكة منتجات وسلة شراء وقسم دفع في تجربة تمرير واحدة تعرض أساسيات واجهات المتاجر العربية على الويب.',
    'single page store', 'متجر صفحة واحدة',
    'Single Page Store: Mini Shop Case Study', 'متجر صفحة واحدة: دراسة حالة Mini Shop',
    'Single page store with cart and checkout in Arabic. Clean UX, responsive layout, and simple e-commerce flow.', 'متجر صفحة واحدة مع سلة ودفع بالعربية. تجربة واضحة، تصميم متجاوب، وتدفق شراء بسيط.',
    '["HTML","CSS","JavaScript"]'::jsonb, '["ecommerce","frontend","ui"]'::jsonb, 'https://github.com/Mohamed-El-Hussainy-gitme/single-page-website', 'https://mohamed-el-hussainy-gitme.github.io/single-page-website/',
    '[{"id":"mini-shop-1","src":"/assets/project1/Screenshot 2025-11-27 151701.png","alt":"Single page store Arabic UI — Mini Shop hero and product grid"},{"id":"mini-shop-2","src":"/assets/project1/Screenshot 2025-11-27 152128.png","alt":"Single page store — product cards and add to cart"},{"id":"mini-shop-3","src":"/assets/project1/Screenshot 2025-11-27 153625.png","alt":"Single page store — cart section UI"},{"id":"mini-shop-4","src":"/assets/project1/Screenshot 2025-11-27 153722.png","alt":"Single page store — cart items and totals"},{"id":"mini-shop-5","src":"/assets/project1/Screenshot 2025-11-27 153802.png","alt":"Single page store — checkout form layout"},{"id":"mini-shop-6","src":"/assets/project1/Screenshot 2025-11-27 154052.png","alt":"Single page store — checkout confirmation flow"},{"id":"mini-shop-7","src":"/assets/project1/Screenshot 2025-11-27 154118.png","alt":"Single page store — responsive layout section"},{"id":"mini-shop-8","src":"/assets/project1/Screenshot 2025-11-27 154445.png","alt":"Single page store — footer and navigation"}]'::jsonb,
    'Users needed a quick single-page store experience in Arabic where product browsing, cart, and checkout feel immediate without multi-page complexity.', 'كان الهدف تقديم متجر صفحة واحدة بالعربية يختصر رحلة الشراء: تصفح المنتجات ثم السلة ثم الدفع بدون تعقيد صفحات كثيرة.',
    'Built a single scrolling layout that keeps product grid, cart, and checkout in one flow, with clear CTA and predictable UI states.', 'تم بناء تخطيط تمرير واحد يدمج شبكة المنتجات والسلة والدفع في مسار واضح مع أزرار وإشعارات حالة بسيطة وسهلة الفهم.',
    'A clean demo for single-page store UX that proves layout, cart interactions, and checkout clarity on desktop and mobile.', 'نتيجة المشروع نموذج عملي لمتجر صفحة واحدة يثبت وضوح الواجهة وتفاعل السلة وسهولة الوصول لخطوة الدفع على الموبايل والديسكتوب.',
    'UI build + vanilla JS cart logic + responsive layout.', 'تنفيذ الواجهة + منطق السلة بـ JavaScript + تصميم متجاوب.',
    'HTML • CSS • JavaScript', 'HTML • CSS • JavaScript',
    '["Define the single-page shopping flow","Design product cards and cart UI states","Implement add-to-cart and quantity updates","Build checkout section and validation hints","Test responsiveness and basic accessibility"]'::jsonb, '["تحديد مسار الشراء في صفحة واحدة","تصميم بطاقات المنتجات وحالات السلة","تنفيذ الإضافة للسلة وتعديل الكميات","إنشاء قسم الدفع وتلميحات التحقق","اختبار التوافق مع الموبايل وإمكانية الوصول"]'::jsonb,
    '[{"q":{"en":"Is this a full e-commerce backend?","ar":"هل هذا متجر كامل بباك إند؟"},"a":{"en":"No. It is a front-end single page store demo focused on UX and cart/checkout behavior.","ar":"لا. هو نموذج واجهة يركز على تجربة المستخدم وتفاعل السلة والدفع."}},{"q":{"en":"Can it be converted to a real store?","ar":"هل يمكن تحويله لمتجر حقيقي؟"},"a":{"en":"Yes. The UI flow can be reused and connected to APIs, payments, and an admin dashboard.","ar":"نعم. يمكن إعادة استخدام نفس التدفق وربطه بـ API وبوابات الدفع ولوحة تحكم."}},{"q":{"en":"Does it support Arabic RTL?","ar":"هل يدعم العربية وRTL؟"},"a":{"en":"Yes. The layout is built with Arabic-first direction and spacing.","ar":"نعم. التخطيط مبني ليكون مناسبًا للعربية واتجاه RTL."}}]'::jsonb,
    'Fake products, add-to-cart flow, cart and checkout section, and a clean one-page responsive layout with navbar and footer.', 'منتجات تجريبية، إضافة للسلة مع عرض سلة الشراء وقسم الدفع، وتخطيط صفحة واحدة متجاوب مع شريط تنقّل وتذييل بسيطين.',
    'Showcasing a compact Arabic shopping flow with product listing, cart, and checkout in a single scrollable page.', 'عرض تجربة تسوّق عربية مضغوطة تجمع عرض المنتجات والسلة والدفع في صفحة واحدة قابلة للتمرير.',
    'Front-end design and implementation using pure HTML, CSS, and JavaScript.', 'تصميم الواجهة وتنفيذها بالكامل باستخدام HTML وCSS وJavaScript فقط.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
    case_study_problem_en, case_study_problem_ar, case_study_solution_en, case_study_solution_ar,
    case_study_outcome_en, case_study_outcome_ar, case_study_role_en, case_study_role_ar,
    case_study_stack_en, case_study_stack_ar, case_study_steps_en, case_study_steps_ar,
    faqs,
    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    2, 'project-2', 'published', true,
    'Real Estate UI', 'Real Estate UI',
    'Arabic RTL real estate interface with advanced filters, dark mode, map, and detailed property pages.', 'واجهة عقارات عربية باتجاه RTL مع فلاتر متقدمة، وضع داكن، خريطة تفاعلية وصفحات تفاصيل كاملة للعقار.',
    'Real Estate UI is a modern React + Vite front-end for browsing properties. It includes a full Arabic RTL layout, advanced filtering by price, area, rooms, property type, and city, text search in titles and locations, a dedicated property details page with image carousel and interactive map built with React Leaflet, plus a dark-mode theme and fully responsive layout.', 'Real Estate UI هو واجهة حديثة مبنية بـ React وVite لاستعراض العقارات. يوفّر تخطيطًا عربيًا كاملًا (RTL)، وفلاتر متقدمة حسب السعر والمساحة وعدد الغرف ونوع العقار والمدينة مع بحث نصي في العناوين والمواقع، وصفحة مخصّصة لتفاصيل العقار تضم معرض صور وخريطة تفاعلية مبنية بـ React Leaflet، بالإضافة إلى وضع داكن وتخطيط متجاوب بالكامل.',
    'real estate UI', 'واجهة عقارات',
    'Real Estate UI: Arabic RTL Case Study', 'واجهة عقارات: دراسة حالة RTL',
    'Real estate UI with advanced filters, property pages, and map. Arabic RTL, dark mode, and responsive UX.', 'واجهة عقارات بفلاتر متقدمة وصفحات تفاصيل وخريطة. دعم RTL، وضع داكن، وتجربة متجاوبة.',
    '["React","Vite","Tailwind CSS","React Router","React Leaflet","Swiper"]'::jsonb, '["real-estate","map","frontend","ui","rtl"]'::jsonb, 'https://github.com/Mohamed-El-Hussainy-gitme/real-estate-ui', 'https://mohamed-el-hussainy-gitme.github.io/real-estate-ui/',
    '[{"id":"real-estate-1","src":"/assets/project2/Screenshot 2025-12-01 003246.png","alt":"Real estate UI — hero and filters panel (Arabic RTL)"},{"id":"real-estate-2","src":"/assets/project2/Screenshot 2025-12-01 003410.png","alt":"Real estate UI — filtered properties grid"},{"id":"real-estate-3","src":"/assets/project2/Screenshot 2025-12-01 003526.png","alt":"Real estate UI — property details page"},{"id":"real-estate-4","src":"/assets/project2/Screenshot 2025-12-01 003635.png","alt":"Real estate UI — property details layout and gallery"},{"id":"real-estate-5","src":"/assets/project2/Screenshot 2025-12-01 003653.png","alt":"Real estate UI — property map section (React Leaflet)"},{"id":"real-estate-6","src":"/assets/project2/Screenshot 2025-12-01 003738.png","alt":"Real estate UI — dark mode view"},{"id":"real-estate-7","src":"/assets/project2/Screenshot 2025-12-01 003810.png","alt":"Real estate UI — ordering / request section"},{"id":"real-estate-8","src":"/assets/project2/Screenshot 2025-12-01 003825.png","alt":"Real estate UI — dark mode details"},{"id":"real-estate-9","src":"/assets/project2/Screenshot 2025-12-01 003846.png","alt":"Real estate UI — dark mode details with map"}]'::jsonb,
    'Property browsing becomes slow when filters and map context are separate. Users needed faster comparison with RTL-first Arabic UI.', 'تصفح العقارات يصبح بطيئًا عندما تكون الفلاتر والخريطة منفصلين. كان المطلوب مقارنة أسرع بواجهة عربية RTL صحيحة.',
    'Built an RTL-first search experience: advanced filters + text search + dedicated details page with gallery and live map context.', 'تم بناء تجربة بحث RTL: فلاتر متقدمة + بحث نصي + صفحة تفاصيل بمعرض صور وخريطة تفاعلية تعطي سياقًا فوريًا للموقع.',
    'A real estate UI that makes discovery and comparison faster, with clear details and map-based trust signals.', 'واجهة عقارات تسهّل الاكتشاف والمقارنة بسرعة، مع تفاصيل واضحة وخريطة تدعم قرار المستخدم.',
    'UI architecture, RTL, filters state, and map integration.', 'هندسة الواجهة، RTL، إدارة حالة الفلاتر، ودمج الخريطة.',
    'React • Tailwind • React Router • Leaflet', 'React • Tailwind • React Router • Leaflet',
    '["Define filter taxonomy (price/area/rooms/type/city)","Design RTL layout and responsive cards","Build filter state + search behavior","Implement details page + gallery","Integrate map and coordinates display","Add dark mode and polish interactions"]'::jsonb, '["تحديد تصنيف الفلاتر (سعر/مساحة/غرف/نوع/مدينة)","تصميم تخطيط RTL وبطاقات متجاوبة","تنفيذ حالة الفلاتر والبحث النصي","إنشاء صفحة التفاصيل ومعرض الصور","دمج الخريطة وإظهار الإحداثيات","إضافة الوضع الداكن وتحسين التفاعلات"]'::jsonb,
    '[{"q":{"en":"Is the map interactive?","ar":"هل الخريطة تفاعلية؟"},"a":{"en":"Yes. It uses React Leaflet with real markers and location context.","ar":"نعم. تم استخدام React Leaflet مع مؤشرات ومعلومات موقع."}},{"q":{"en":"Does it support Arabic RTL properly?","ar":"هل يدعم RTL للعربية بشكل صحيح؟"},"a":{"en":"Yes. Layout direction, spacing, and UI alignment are RTL-first.","ar":"نعم. الاتجاه والمسافات ومحاذاة العناصر تم ضبطها للعربية."}},{"q":{"en":"Can this UI connect to a backend?","ar":"هل يمكن ربط الواجهة بباك إند؟"},"a":{"en":"Yes. Filters and routes are ready to be connected to APIs.","ar":"نعم. الفلاتر والمسارات جاهزة للربط مع API."}}]'::jsonb,
    'Hero landing, advanced filters, Arabic RTL layout, property cards grid, details page with gallery, interactive map, and dark mode toggle.', 'واجهة رئيسية مع قسم Hero، فلاتر متقدمة، تخطيط عربي RTL كامل، شبكة بطاقات للعقارات، صفحة تفاصيل مع معرض صور، خريطة تفاعلية، وزر للتبديل إلى الوضع الداكن.',
    'Make searching and comparing properties fast through filters, search, and map navigation.', 'جعل البحث عن العقارات ومقارنتها أسرع عبر الفلاتر والبحث النصي والتصفح من خلال الخريطة التفاعلية.',
    'Front-end architecture, UI/UX design, RTL layout, and dark-mode implementation.', 'هندسة الواجهة الأمامية، تصميم واجهة وتجربة المستخدم، ضبط RTL، وتنفيذ نمط الوضع الداكن.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
    case_study_problem_en, case_study_problem_ar, case_study_solution_en, case_study_solution_ar,
    case_study_outcome_en, case_study_outcome_ar, case_study_role_en, case_study_role_ar,
    case_study_stack_en, case_study_stack_ar, case_study_steps_en, case_study_steps_ar,
    faqs,
    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    3, 'project-3', 'published', true,
    'Admin Control Dashboard', 'لوحة تحكم إدارية متكاملة',
    'Admin dashboard with analytics, users, orders, products, settings, notifications, and themes.', 'لوحة تحكم إدارية تضم التحليلات والمستخدمين والطلبات والمنتجات والإعدادات والتنبيهات والسمات.',
    'A production-style admin dashboard built with React, Vite, Tailwind CSS, and Zustand. It includes a simple mock login flow, protected routes, responsive sidebar and topbar, analytics with Recharts, rich tables for users, orders, and products, plus notifications, themes, dark mode, and English/Arabic support.', 'لوحة تحكم إدارية احترافية مبنية بـ React وVite وTailwind CSS وZustand. توفّر تدفّق تسجيل دخول تجريبي، ومسارات محمية، وشريطًا جانبيًا ورأسيًا متجاوبين، وصفحات تحليلات بمخططات Recharts، وجداول متقدمة للمستخدمين والطلبات والمنتجات، إلى جانب نظام تنبيهات وسمات متعددة ووضع داكن ودعم للغتين العربية والإنجليزية.',
    'admin dashboard', 'لوحة تحكم',
    'Admin Dashboard: Tables & Analytics Case Study', 'لوحة تحكم: دراسة حالة الجداول والتحليلات',
    'Admin dashboard with analytics, tables, routing, and themes. Clean UX, protected routes, and bilingual UI.', 'لوحة تحكم بتحليلات وجداول ومسارات وسمات. تجربة نظيفة، مسارات محمية، ودعم لغتين.',
    '["React","Vite","TypeScript","Tailwind CSS","Zustand","React Router","Recharts","Framer Motion"]'::jsonb, '["dashboard","admin","ui","frontend","rtl"]'::jsonb, 'https://github.com/Mohamed-El-Hussainy-gitme/dashboard-admin', 'https://mohamed-el-hussainy-gitme.github.io/dashboard-admin',
    '[{"id":"admin-1","src":"/assets/project3/Screenshot 2025-12-02 190940.png","alt":"Admin dashboard — analytics overview"},{"id":"admin-2","src":"/assets/project3/Screenshot 2025-12-02 191014.png","alt":"Admin dashboard — analytics sales view"},{"id":"admin-3","src":"/assets/project3/Screenshot 2025-12-02 191048.png","alt":"Admin dashboard — users table"},{"id":"admin-4","src":"/assets/project3/Screenshot 2025-12-02 191205.png","alt":"Admin dashboard — users sorting and filters"},{"id":"admin-5","src":"/assets/project3/Screenshot 2025-12-02 191304.png","alt":"Admin dashboard — orders table sorting"},{"id":"admin-6","src":"/assets/project3/Screenshot 2025-12-02 191353.png","alt":"Admin dashboard — products management table"},{"id":"admin-7","src":"/assets/project3/Screenshot 2025-12-02 191426.png","alt":"Admin dashboard — notifications center"},{"id":"admin-8","src":"/assets/project3/Screenshot 2025-12-02 191505.png","alt":"Admin dashboard — appearance settings"},{"id":"admin-9","src":"/assets/project3/Screenshot 2025-12-02 191606.png","alt":"Admin dashboard — Arabic RTL settings"},{"id":"admin-10","src":"/assets/project3/Screenshot 2025-12-02 191634.png","alt":"Admin dashboard — dark mode settings"}]'::jsonb,
    'Dashboards fail when tables are inconsistent, filters reset, and navigation is unclear. Admin users needed predictable workflows.', 'لوحات التحكم تفشل عندما تكون الجداول غير ثابتة والفلاتر تُعاد دون سبب والتنقل غير واضح. كان المطلوب مسار إداري متوقع وسهل.',
    'Built a structured admin dashboard: protected routes, consistent navigation, analytics, and rich tables with clear states (loading/empty/error).', 'تم بناء لوحة تحكم منظمة: مسارات محمية، تنقل ثابت، تحليلات، وجداول قوية مع حالات واضحة (تحميل/فارغ/خطأ).',
    'A production-style admin dashboard UI that feels stable, fast to use, and easy to scale for more modules.', 'نتيجة المشروع لوحة تحكم بطابع إنتاجي تبدو مستقرة وسريعة وسهلة التوسع لإضافة أقسام جديدة.',
    'Dashboard UI engineering + state design + table patterns.', 'هندسة واجهة لوحة التحكم + تصميم الحالة + أنماط الجداول.',
    'React • TypeScript • Zustand • Recharts', 'React • TypeScript • Zustand • Recharts',
    '["Design navigation and module layout","Define protected routes and auth mock flow","Build table components (sorting, pagination patterns)","Add analytics charts and summary cards","Implement themes + dark mode + RTL support","Polish animations and responsiveness"]'::jsonb, '["تصميم التنقل وهيكلة الأقسام","تحديد المسارات المحمية وتدفق دخول تجريبي","بناء مكونات الجداول (فرز/أنماط ترقيم)","إضافة مخططات التحليلات وبطاقات الملخص","تنفيذ السمات والوضع الداكن ودعم RTL","تحسين الحركة والاستجابة للموبايل"]'::jsonb,
    '[{"q":{"en":"Does it include real authentication?","ar":"هل يوجد تسجيل دخول حقيقي؟"},"a":{"en":"It includes a mock flow and protected routes pattern. It can be connected to a real auth system.","ar":"يوجد تدفق تجريبي ونمط مسارات محمية ويمكن ربطه بمصادقة حقيقية."}},{"q":{"en":"Are tables reusable?","ar":"هل الجداول قابلة لإعادة الاستخدام؟"},"a":{"en":"Yes. The UI follows reusable table patterns and consistent states.","ar":"نعم. تم بناء أنماط جداول قابلة لإعادة الاستخدام مع حالات ثابتة."}},{"q":{"en":"Can it become a real admin for a store?","ar":"هل تصلح كلوحة لمتجر؟"},"a":{"en":"Yes. Modules like orders/products/users are already structured for a store admin.","ar":"نعم. أقسام الطلبات والمنتجات والمستخدمين منظمة لتناسب لوحة متجر."}}]'::jsonb,
    'Analytics, users, orders, products, settings, notifications, themes, dark mode, and a responsive dashboard layout.', 'صفحات تحليلات ولوحات بيانات، إدارة مستخدمين وطلبات ومنتجات، إعدادات وتنبيهات وسمات متعددة، ووضع داكن في تخطيط لوحة تحكم متجاوب.',
    'Designing a clean admin UX with protected routes, flexible layout, and clear data presentation.', 'تصميم تجربة لوحة تحكم نظيفة مع مسارات محمية وتخطيط مرن وعرض واضح ومنظّم للبيانات.',
    'Front-end engineering, state management with Zustand, chart integration, and UI system.', 'تطوير الواجهة الأمامية، وإدارة الحالة باستخدام Zustand، وربط المخططات، وبناء نظام مكوّنات الواجهة.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
