    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    4, 'project-4', 'published', true,
    'Animation Studio', 'Animation Studio – محرر حركات للويب',
    'Web-based animation editor with timeline, layers, live preview, and export to CSS, HTML, JSON, and React.', 'محرر حركات على الويب بخط زمني وطبقات ومعاينة حيّة وتصدير إلى CSS وHTML وJSON وReact.',
    'Animation Studio is a lightweight front-end animation editor that runs entirely in the browser. It gives you a mini timeline, layers panel, and live preview so you can design motion visually, then export clean CSS keyframes, HTML structure, JSON config, or a React component using Framer Motion, with undo/redo and localStorage-powered project saving.', 'Animation Studio هو محرر حركات خفيف يعمل بالكامل داخل المتصفّح. يوفّر خطًا زمنيًا مصغّرًا ولوحة طبقات ومعاينة مباشرة لتصميم الحركة بصريًا، مع تصدير كود CSS جاهز أو هيكل HTML أو إعدادات JSON أو مكوّن React يعتمد على Framer Motion، بالإضافة إلى دعم التراجع/الإعادة وحفظ المشاريع في المتصفح عبر localStorage.',
    'web animation', 'تصميم حركات',
    'Web Animation Editor: Animation Studio Case Study', 'تصميم حركات: دراسة حالة Animation Studio',
    'Web animation editor with timeline and export. Generate CSS keyframes and React motion code from a visual UI.', 'محرر حركات بخط زمني وتصدير. إنشاء CSS keyframes وكود React للحركة من واجهة بصرية.',
    '["HTML","CSS","TypeScript","Framer Motion"]'::jsonb, '["animation","motion","frontend","ui"]'::jsonb, 'https://github.com/Mohamed-El-Hussainy-gitme/animation-studio', 'https://mohamed-el-hussainy-gitme.github.io/animation-studio/',
    '[{"id":"animation-1","src":"/assets/project4/Screenshot 2025-12-01 222924.png","alt":"Web animation editor — timeline and layers panel"},{"id":"animation-2","src":"/assets/project4/Screenshot 2025-12-01 223329.png","alt":"Web animation editor — live preview and controls"},{"id":"animation-3","src":"/assets/project4/Screenshot 2025-12-01 223707.png","alt":"Web animation editor — export panel for CSS/HTML/JSON"},{"id":"animation-4","src":"/assets/project4/Screenshot 2025-12-01 223957.png","alt":"Web animation editor — exported React motion code"}]'::jsonb,
    'Developers often waste time rewriting animation prototypes into production code. They need web animation tools that export clean code.', 'المطورون يضيعون وقتًا في تحويل نماذج الحركة إلى كود إنتاجي. كان المطلوب أداة تصميم حركات تصدر كودًا نظيفًا.',
    'Created a browser-based web animation editor with timeline, layers, preview, and export to CSS keyframes and React motion components.', 'تم إنشاء محرر حركات يعمل داخل المتصفح مع خط زمني وطبقات ومعاينة وتصدير إلى CSS keyframes ومكوّنات React للحركة.',
    'A practical motion workflow: design visually, preview instantly, and export code ready to paste into real projects.', 'سير عمل عملي: تصميم بصري ثم معاينة فورية ثم تصدير كود قابل للاستخدام مباشرة داخل مشاريع حقيقية.',
    'Editor UX + animation logic + export formats.', 'UX للمحرر + منطق الحركة + صيغ التصدير.',
    'TypeScript • Framer Motion • CSS keyframes', 'TypeScript • Framer Motion • CSS keyframes',
    '["Define timeline model and layers structure","Build preview renderer and playback controls","Add undo/redo and local saving","Design export pipeline (CSS/HTML/JSON/React)","Polish UI states and responsive layout"]'::jsonb, '["تحديد نموذج الخط الزمني وبنية الطبقات","بناء المعاينة والتحكم في التشغيل","إضافة التراجع/الإعادة والحفظ المحلي","تصميم نظام التصدير (CSS/HTML/JSON/React)","تحسين حالات الواجهة والتوافق مع الموبايل"]'::jsonb,
    '[{"q":{"en":"Does it export production-ready code?","ar":"هل التصدير مناسب للإنتاج؟"},"a":{"en":"It exports clean templates you can paste and adapt. The goal is reducing rewrite time.","ar":"يصدر قوالب نظيفة قابلة للصق والتعديل بهدف تقليل وقت إعادة الكتابة."}},{"q":{"en":"Why both CSS and React exports?","ar":"لماذا تصدير CSS وReact معًا؟"},"a":{"en":"Some projects need pure CSS; others use React motion. The tool supports both workflows.","ar":"بعض المشاريع تحتاج CSS فقط والبعض يستخدم React motion لذلك دعمنا المسارين."}},{"q":{"en":"Can designs be saved and resumed?","ar":"هل يمكن حفظ المشروع واستكماله لاحقًا؟"},"a":{"en":"Yes. Projects are saved locally and can be resumed quickly.","ar":"نعم. يتم حفظ المشاريع محليًا ويمكن استكمالها بسهولة."}}]'::jsonb,
    'Timeline, layers panel, live preview, undo/redo, device presets, and export to CSS, HTML, JSON, and React.', 'خط زمني ولوحة طبقات ومعاينة حيّة، مع تراجع وتقدّم، وخيارات أجهزة مختلفة، وتصدير إلى CSS وHTML وJSON وReact.',
    'Make motion design approachable for front-end developers through a browser-based editor with clean exports.', 'تبسيط تصميم الحركات لمطوّري الواجهة الأمامية عبر محرر يعمل داخل المتصفح ويصدر كودًا نظيفًا.',
    'Product idea, editor UX, animation engine, and export pipeline.', 'ابتكار الفكرة، UX للمحرر، منطق الحركة، ونظام التصدير.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
    case_study_problem_en, case_study_problem_ar, case_study_solution_en, case_study_solution_ar,
    case_study_outcome_en, case_study_outcome_ar, case_study_role_en, case_study_role_ar,
    case_study_stack_en, case_study_stack_ar, case_study_steps_en, case_study_steps_ar,
    faqs,
    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    5, 'project-5', 'published', true,
    'HoloSpace OS', 'HoloSpace OS – نظام تشغيل ويب ثلاثي الأبعاد',
    '3D web operating system with desktop, windows, music player, gallery, notes, and system settings.', 'نظام تشغيل ويب ثلاثي الأبعاد مع سطح مكتب ونوافذ وتطبيقات مدمجة مثل مشغّل الموسيقى ومعرض الصور والملاحظات والإعدادات.',
    'HoloSpace OS is a 3D spatial web operating system built with React, Vite, TypeScript, TailwindCSS, React Three Fiber, and Framer Motion. It simulates a futuristic desktop with glassmorphism UI, animated dock, launcher, command palette, notifications panel, and multiple apps such as Music, Gallery, Notes, and Settings with theme, profile, and club-mode visual/audio effects.', 'HoloSpace OS هو نظام تشغيل ويب ثلاثي الأبعاد مبني بـ React وVite وTypeScript وTailwindCSS وReact Three Fiber وFramer Motion. يقدّم سطح مكتب مستقبليًا بتصميم زجاجي، وشريط تطبيقات متحرك، وقائمة إطلاق، ولوحة أوامر، ولوحة تنبيهات، وتطبيقات مدمجة مثل مشغّل الموسيقى ومعرض الصور والملاحظات والإعدادات مع تحكم في السمات والملفات الشخصية وتأثيرات بصرية وصوتية مخصّصة لوضع Club Mode.',
    '3D web experience', 'تجربة ثلاثية الأبعاد',
    '3D Web Experience: HoloSpace OS Case Study', 'تجربة ثلاثية الأبعاد: دراسة حالة HoloSpace',
    '3D web desktop with apps, themes, and motion. WebGL-style UI with window manager and interactive modules.', 'سطح مكتب ثلاثي الأبعاد مع تطبيقات وسمات وحركة. واجهة WebGL بمدير نوافذ وتفاعل متقدم.',
    '["React","Vite","TypeScript","Tailwind CSS","React Three Fiber","@react-three/drei","Framer Motion","HTML5 Audio"]'::jsonb, '["3d","webgl","frontend","ui","motion"]'::jsonb, 'https://github.com/Mohamed-El-Hussainy-gitme/holospace-web', 'https://mohamed-el-hussainy-gitme.github.io/holospace-web/',
    '[{"id":"holospace-1","src":"/assets/project5/Screenshot 2025-12-06 235132.png","alt":"3D web desktop — main workspace"},{"id":"holospace-2","src":"/assets/project5/Screenshot 2025-12-06 235225.png","alt":"3D web desktop — music player and visualizer"},{"id":"holospace-3","src":"/assets/project5/Screenshot 2025-12-06 235303.png","alt":"3D web desktop — gallery and windows manager"},{"id":"holospace-4","src":"/assets/project5/Screenshot 2025-12-06 235404.png","alt":"3D web desktop — themes and UI variations"},{"id":"holospace-5","src":"/assets/project5/Screenshot 2025-12-06 235639.png","alt":"3D web desktop — notes app"},{"id":"holospace-6","src":"/assets/project5/Screenshot 2025-12-06 235756.png","alt":"3D web desktop — settings appearance"},{"id":"holospace-7","src":"/assets/project5/Screenshot 2025-12-06 235829.png","alt":"3D web desktop — quality settings"},{"id":"holospace-8","src":"/assets/project5/Screenshot 2025-12-06 235902.png","alt":"3D web desktop — motion and FX settings"},{"id":"holospace-9","src":"/assets/project5/screenshot 1.png","alt":"3D web desktop — mobile music player"},{"id":"holospace-10","src":"/assets/project5/screenshot 2.png","alt":"3D web desktop — mobile home screen"},{"id":"holospace-11","src":"/assets/project5/screenshot 3.png","alt":"3D web desktop — mobile theme view"}]'::jsonb,
    'Building a 3D web experience often becomes a performance problem or a UI chaos. The goal was a usable 3D desktop that still feels like a real product.', 'تجارب الويب ثلاثية الأبعاد غالبًا تتحول لمشكلة أداء أو فوضى واجهة. الهدف كان بناء تجربة ثلاثية الأبعاد قابلة للاستخدام وتشبه منتجًا حقيقيًا.',
    'Designed a 3D web desktop with clear UI layers: window manager, dock, launcher, and apps with theming and motion that does not overwhelm.', 'تم تصميم سطح مكتب ثلاثي الأبعاد بطبقات واجهة واضحة: مدير نوافذ وشريط تطبيقات وقائمة تشغيل وتطبيقات مع سمات وحركة محسوبة بدون إزعاج.',
    'A demo OS that proves interaction patterns (windows, apps, settings) inside a 3D web experience with responsive behavior.', 'نتيجة المشروع نظام تجريبي يثبت أنماط التفاعل (نوافذ/تطبيقات/إعدادات) داخل تجربة ثلاثية الأبعاد مع دعم الموبايل.',
    '3D scene + UI layering + motion + app modules.', 'المشهد ثلاثي الأبعاد + طبقات الواجهة + الحركة + بناء التطبيقات.',
    'React Three Fiber • TypeScript • Framer Motion', 'React Three Fiber • TypeScript • Framer Motion',
    '["Define desktop interaction model (windows, focus, z-index)","Build 3D scene + camera behaviors","Implement window manager and launcher","Add apps (music, gallery, notes, settings)","Create theming and profiles system","Tune performance and FX settings"]'::jsonb, '["تحديد نموذج التفاعل (نوافذ/تركيز/ترتيب الطبقات)","بناء المشهد والكاميرا","تنفيذ مدير النوافذ وقائمة التشغيل","إضافة تطبيقات (موسيقى/معرض/ملاحظات/إعدادات)","إنشاء نظام السمات والملفات الشخصية","ضبط الأداء وإعدادات المؤثرات"]'::jsonb,
    '[{"q":{"en":"Is this built with WebGL?","ar":"هل المشروع مبني بـ WebGL؟"},"a":{"en":"Yes, through React Three Fiber with interactive UI layered on top.","ar":"نعم عبر React Three Fiber مع واجهة فوق المشهد."}},{"q":{"en":"Does it work on mobile?","ar":"هل يعمل على الموبايل؟"},"a":{"en":"Yes. Core modules have responsive views and mobile-friendly interaction.","ar":"نعم. توجد واجهات مناسبة للموبايل وتفاعل مبسط."}},{"q":{"en":"Can it be turned into a product?","ar":"هل يمكن تحويله لمنتج؟"},"a":{"en":"Yes. The architecture supports adding apps and improving performance progressively.","ar":"نعم. المعمارية تسمح بإضافة تطبيقات وتحسين الأداء تدريجيًا."}}]'::jsonb,
    '3D desktop, glassmorphism UI, animated dock and launcher, window manager, notifications panel, and multiple built-in apps.', 'سطح مكتب ثلاثي الأبعاد، واجهة زجاجية، شريط تطبيقات وقائمة إطلاق متحركة، مدير نوافذ، لوحة تنبيهات، وتطبيقات مدمجة متعددة.',
    'Exploring spatial OS concepts in the browser using WebGL, motion, and system-level theming and profiles.', 'استكشاف فكرة أنظمة التشغيل المكانية داخل المتصفّح باستخدام WebGL والحركة ونظام سمات وملفات شخصية على مستوى النظام.',
    'System design, 3D scene composition, UI design, and front-end implementation.', 'تصميم النظام، وبناء المشهد الثلاثي الأبعاد، وتصميم الواجهة، وتنفيذ الواجهة الأمامية.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
