    highlight_role_en, highlight_role_ar
  ) VALUES (
    6, 'project-6', 'published', true,
    'PulseReach Media Website', 'PulseReach Media – موقع وكالة سوشيال ميديا (صفحات بيع باقات)',
    'Conversion-focused bilingual landing pages for social media management packages (WordPress + coded templates).', 'صفحات بيع باقات سوشيال ميديا ثنائية اللغة مع قوالب مبرمجة تركّز على التحويل داخل ووردبريس.',
    'PulseReach Media is a bilingual (AR/EN) marketing agency website built on WordPress using Astra Child Theme and custom coded page templates. The project focuses on clean, modern UI, strong conversion sections (hero, social proof, pricing, FAQs, CTAs), RTL-first Arabic layout, and scalable template-based pages for Services, Packages, Results, and Contact with WPForms integration.', 'PulseReach Media هو موقع ثنائي اللغة (عربي/إنجليزي) لوكالة تسويق وسوشيال ميديا مبني على WordPress باستخدام Astra Child Theme وقوالب صفحات مبرمجة (Coded Templates). يركّز المشروع على واجهة حديثة وتجربة تحويل قوية عبر أقسام الهيرو، إثبات اجتماعي، الباقات والأسعار، الأسئلة الشائعة، وCTA واضح، مع دعم RTL للعربية وقابلية التوسع لصفحات الخدمات والباقات والنتائج والتواصل ودمج WPForms.',
    'WordPress website', 'موقع ووردبريس',
    'WordPress Website: PulseReach Media Case Study', 'موقع ووردبريس: دراسة حالة PulseReach',
    'WordPress website with bilingual landing pages and conversion sections. RTL-first Arabic, pricing, FAQs, and CTAs.', 'موقع ووردبريس بصفحات بيع ثنائية اللغة. RTL للعربية، باقات، FAQ، وCTA واضح للتحويل.',
    '["WordPress","PHP","Astra (Child Theme)","HTML5","CSS (Design System Variables)","WPForms","Rank Math SEO"]'::jsonb, '["wordpress","landing","seo","technical-seo","schema","rtl"]'::jsonb, '', 'https://pulsereachmedia.wuaze.com/',
    '[{"id":"pulsereach-1","src":"/assets/project6/1.png","alt":"WordPress website — Arabic hero and conversion layout"},{"id":"pulsereach-2","src":"/assets/project6/2.png","alt":"WordPress website — pricing and packages section"},{"id":"pulsereach-3","src":"/assets/project6/3.png","alt":"WordPress website — services landing section"},{"id":"pulsereach-4","src":"/assets/project6/4.png","alt":"WordPress website — results/case studies page"},{"id":"pulsereach-5","src":"/assets/project6/5.png","alt":"WordPress website — contact page with form CTA"},{"id":"pulsereach-6","src":"/assets/project6/6.png","alt":"WordPress website — responsive navigation on mobile"},{"id":"pulsereach-7","src":"/assets/project6/7.png","alt":"WordPress website — mobile layout view"},{"id":"pulsereach-8","src":"/assets/project6/8.png","alt":"WordPress website — mobile pricing view"},{"id":"pulsereach-9","src":"/assets/project6/9.png","alt":"WordPress website — mobile FAQ and CTA blocks"}]'::jsonb,
    'Agency websites fail when packages are unclear and CTAs are weak. The goal was a WordPress website built for conversion in AR/EN.', 'مواقع الوكالات تفشل عندما تكون الباقات غير واضحة وCTA ضعيف. كان المطلوب موقع ووردبريس مصمم للتحويل بالعربية والإنجليزية.',
    'Implemented conversion-first landing templates: hero + proof + pricing + FAQ + CTA, with RTL-first Arabic and scalable template structure.', 'تم تنفيذ قوالب صفحات بيع: هيرو + إثبات اجتماعي + باقات + FAQ + CTA، مع RTL للعربية وبنية Templates قابلة للتوسع.',
    'A clearer sales structure that guides visitors to choose a package and contact through a single primary CTA.', 'بنية بيع أوضح تقود الزائر لاختيار باقة والتواصل عبر CTA أساسي واحد بدل تشتت الأزرار.',
    'Template coding + UI structure + SEO basics.', 'برمجة Templates + هيكلة الواجهة + أساسيات SEO.',
    'WordPress • PHP templates • RankMath SEO', 'WordPress • قوالب PHP • RankMath SEO',
    '["Define conversion sections and package layout","Implement RTL-first templates and reusable blocks","Integrate forms and trackable CTAs","Optimize SEO titles/descriptions and schema","Test responsiveness and page speed basics"]'::jsonb, '["تحديد أقسام التحويل وبنية الباقات","تنفيذ Templates للعربية وBlocks قابلة لإعادة الاستخدام","دمج النماذج وCTA قابلة للقياس","تهيئة SEO (عناوين/وصف/سكيما)","اختبار الاستجابة وأساسيات السرعة"]'::jsonb,
    '[{"q":{"en":"Why WordPress for this project?","ar":"لماذا ووردبريس؟"},"a":{"en":"It enables fast iteration for content and packages while keeping templates consistent and SEO-friendly.","ar":"يسمح بتعديل المحتوى والباقات بسرعة مع الحفاظ على قوالب ثابتة وداعمة لـ SEO."}},{"q":{"en":"Is Arabic RTL handled correctly?","ar":"هل RTL مضبوط؟"},"a":{"en":"Yes. The layout is RTL-first with appropriate spacing and alignment.","ar":"نعم. تم ضبط الاتجاه والمسافات والمحاذاة للعربية."}},{"q":{"en":"Can more landing pages be added?","ar":"هل يمكن إضافة صفحات بيع جديدة؟"},"a":{"en":"Yes. Template-driven structure makes it easy to add more pages consistently.","ar":"نعم. بنية القوالب تجعل إضافة صفحات جديدة سهلة وبنفس الجودة."}}]'::jsonb,
    'Bilingual AR/EN, RTL-first layout, coded templates for 8 pages, pricing and conversion sections, reusable design system, and fast iteration inside WordPress.', 'ثنائي اللغة عربي/إنجليزي، دعم RTL بشكل صحيح، قوالب مبرمجة لعدة صفحات (حتى 8 صفحات)، أقسام تحويل قوية (باقات/CTA/FAQ)، نظام تصميم CSS قابل لإعادة الاستخدام، وسهولة تطوير وتعديل داخل ووردبريس.',
    'High-conversion landing structure, clean responsive UI, SEO-ready pages, and scalable template-driven architecture for services and packages.', 'هيكلة Landing Pages عالية التحويل، تصميم Responsive نظيف، جاهزية SEO، وبنية Templates قابلة للتوسع لصفحات الخدمات والباقات.',
    'UI structure, custom template coding (PHP), design system CSS, content architecture, and basic SEO setup.', 'بناء الهيكلة والواجهات، برمجة قوالب الصفحات (PHP)، تصميم نظام CSS، تنظيم المحتوى وأقسام التحويل، وتجهيز أساسيات SEO.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
