    highlight_role_en, highlight_role_ar
  ) VALUES (
    7, 'project-7', 'published', true,
    'Arab Tourism Platform', 'Arab Tourism Platform – منصة المعالم السياحية العربية',
    'Arabic-first static tourism directory with an interactive SVG map, country theming, and rich landmark pages (Next.js Export).', 'دليل سياحي عربي أولًا بصفحات دول ومعالم + خريطة SVG تفاعلية + ثيمات لكل دولة، جاهز للتصدير كـ Static (Next.js Export).',
    'Arab Tourism Platform is a modern Arabic-first tourism directory built with Next.js (App Router), React, and Tailwind CSS. It provides a country → landmarks browsing flow, an interactive SVG map of the Arab world (d3-geo + topojson + world-atlas), and detailed landmark pages including long narrative text, sources, coordinates, and image-search suggestions. The project is fully static-export ready (outputs an /out folder) and can be deployed to shared hosting like InfinityFree with no backend—data is shipped locally as JSON/CSV and generated into static pages.', 'Arab Tourism Platform هي منصة دليل سياحي عربية أولًا مبنية باستخدام Next.js (App Router) وReact وTailwind CSS. توفر تجربة تصفح دولة → معالم، وخريطة SVG تفاعلية للوطن العربي (d3-geo + topojson-client + world-atlas)، وصفحات معالم غنية تحتوي على سرد عربي طويل، مصادر، إحداثيات، واقتراحات بحث عن الصور. المشروع مُجهّز للتصدير كـ Static بالكامل (ينتج مجلد /out) ويمكن رفعه على استضافات Shared مثل InfinityFree بدون أي Backend، حيث يتم الاعتماد على بيانات محلية JSON/CSV تُحوّل إلى صفحات ثابتة.',
    'tourism website', 'موقع سياحي',
    'Tourism Website: Arab Tourism Platform Case Study', 'موقع سياحي: دراسة حالة منصة السياحة',
    'Tourism website with interactive SVG map and static export. Country pages, landmark pages, and fast browsing.', 'موقع سياحي بخريطة SVG تفاعلية وتصدير Static. صفحات دول ومعالم وتصفح سريع.',
    '["Next.js (App Router)","React","Tailwind CSS","Static Export (output: ''export'')","d3-geo","topojson-client","world-atlas","Local JSON/CSV Dataset"]'::jsonb, '["tourism","map","frontend","seo"]'::jsonb, '', 'https://arabesque.lovestoblog.com/',
    '[{"id":"arab-tourism-1","src":"/assets/project7/1.png","alt":"Tourism website — home with SVG map and countries directory"},{"id":"arab-tourism-2","src":"/assets/project7/2.png","alt":"Tourism website — SVG map interactive states"},{"id":"arab-tourism-3","src":"/assets/project7/3.png","alt":"Tourism website — country page with themed header and cards"},{"id":"arab-tourism-4","src":"/assets/project7/4.png","alt":"Tourism website — landmark details page with long narrative"},{"id":"arab-tourism-5","src":"/assets/project7/5.png","alt":"Tourism website — sources, coordinates, and image search suggestions"},{"id":"arab-tourism-6","src":"/assets/project7/6.png","alt":"Tourism website — search results for landmarks"},{"id":"arab-tourism-7","src":"/assets/project7/7.png","alt":"Tourism website — mobile responsive map layout"},{"id":"arab-tourism-8","src":"/assets/project7/8.png","alt":"Tourism website — country theming via CSS variables"},{"id":"arab-tourism-9","src":"/assets/project7/Screenshot_2025-12-28-22-08-38-245_com.android.chrome.jpg","alt":"Tourism website — mobile country details view"},{"id":"arab-tourism-10","src":"/assets/project7/Screenshot_2025-12-28-22-07-12-883_com.android.chrome[1].jpg","alt":"Tourism website — mobile landmark page view"}]'::jsonb,
    'Tourism directories become heavy when they rely on backend queries for every page. The project needed a fast tourism website that works on shared hosting.', 'مواقع الأدلة السياحية تصبح ثقيلة عندما تعتمد على باك إند لكل صفحة. كان المطلوب موقع سياحي سريع يعمل على استضافات Shared بدون باك إند.',
    'Built a static-export architecture: dataset-driven pages (countries/landmarks) + interactive SVG map + long landmark pages with sources and coordinates.', 'تم بناء بنية Static Export: صفحات تولَّد من Dataset (دول/معالم) + خريطة SVG تفاعلية + صفحات معالم غنية بسرد ومصادر وإحداثيات.',
    'Fast browsing, easy deployment on shared hosting, and scalable content structure for adding more landmarks without backend complexity.', 'تصفح سريع ونشر سهل على الاستضافات المشتركة وبنية قابلة للتوسع لإضافة معالم جديدة بدون تعقيد باك إند.',
    'UI/UX + static routing + map integration + dataset utilities.', 'UI/UX + مسارات Static + دمج الخريطة + أدوات البيانات.',
    'Next.js export • d3-geo • topojson • Tailwind', 'Next.js export • d3-geo • topojson • Tailwind',
    '["Design country → landmark browsing flow","Build interactive SVG map and theming","Create static pages from JSON/CSV dataset","Write long landmark page structure (facts/sources)","Prepare static export and hosting-ready output"]'::jsonb, '["تصميم تدفق دولة → معالم","بناء خريطة SVG تفاعلية ونظام ثيمات","توليد صفحات ثابتة من JSON/CSV","إنشاء بنية صفحة المعلم (حقائق/مصادر)","تجهيز التصدير والنشر على الاستضافة"]'::jsonb,
    '[{"q":{"en":"Why static export?","ar":"لماذا Static Export؟"},"a":{"en":"It removes backend cost and keeps pages fast on shared hosting.","ar":"لأنه يلغي تكلفة الباك إند ويجعل الصفحات سريعة على الاستضافات المشتركة."}},{"q":{"en":"Is the map usable on mobile?","ar":"هل الخريطة مناسبة للموبايل؟"},"a":{"en":"Yes. Interaction is designed for tap and focus, not hover-only.","ar":"نعم. تم ضبط التفاعل للمس والضغط وليس hover فقط."}},{"q":{"en":"Can new landmarks be added easily?","ar":"هل إضافة معالم جديدة سهلة؟"},"a":{"en":"Yes. Add data entries and rebuild; pages are generated automatically.","ar":"نعم. بإضافة البيانات ثم إعادة البناء يتم توليد الصفحات تلقائيًا."}}]'::jsonb,
    'Arabic-first UI, country → landmarks directory, interactive SVG map (d3-geo/topojson), per-country theming via CSS variables, and rich landmark pages (narrative + sources + coordinates). Fully static export to /out for shared hosting.', 'واجهة عربية أولًا، دليل دول → معالم، خريطة SVG تفاعلية (d3-geo/topojson)، ثيم لكل دولة عبر CSS Variables، وصفحات معالم غنية (سرد + مصادر + إحداثيات). تصدير Static كامل إلى /out لرفع المشروع على استضافات Shared.',
    'Performance-friendly static architecture, clean responsive UI, scalable dataset-driven pages, and map usability on mobile (hover/focus/tap).', 'بنية Static سريعة وخفيفة، واجهة Responsive نظيفة، صفحات قابلة للتوسع بالاعتماد على Dataset محلي، وتحسين تجربة الخريطة على الموبايل (tap/hover/focus).',
    'UI/UX implementation, components system, static routing, SVG map integration, theming system, and data utilities for JSON/CSV.', 'تنفيذ الواجهات وتجربة المستخدم، بناء نظام مكوّنات، إعداد صفحات Static، دمج خريطة SVG، بناء نظام الثيمات، وتجهيز أدوات بيانات JSON/CSV.'
  );
