    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    8, 'E-ecommerce-website-development', 'published', true,
    'NODA E-commerce Website Development', 'تطوير متجر NODA الإلكتروني',
    'Full store + admin dashboard + database for operational speed.', 'متجر كامل + لوحة تحكم + قاعدة بيانات لتسريع الإدارة والبيع.',
    'A full e-commerce build that includes a customer-facing storefront, an admin dashboard for products/orders, and a structured database layer. The goal was to reduce friction in the buying flow while keeping daily operations simple for the business team.', 'مشروع متجر إلكتروني متكامل يشمل واجهة العميل، لوحة تحكم لإدارة المنتجات والطلبات، وقاعدة بيانات منظمة. الهدف كان تقليل الاحتكاك في رحلة الشراء مع الحفاظ على إدارة يومية سهلة وسريعة لفريق العمل.',
    'e-commerce website', 'متجر إلكتروني',
    'E-commerce Website: NODA Store Case Study', 'متجر إلكتروني: دراسة حالة مشروع NODA',
    'E-commerce website + admin dashboard + database. Clean UX, fast flows, and SEO-ready structure for real sales.', 'متجر إلكتروني + لوحة تحكم + قاعدة بيانات. تجربة شراء واضحة، إدارة أسرع، وبنية جاهزة لـ SEO لتحقيق مبيعات.',
    '["E-commerce","Admin Dashboard","Database"]'::jsonb, '["ecommerce","admin","database","seo"]'::jsonb, '', 'https://e-commerce-website.42web.io/',
    '[{"id":"E-commerce-01","src":"/assets/E-commerce/1.png","alt":"E-commerce website — NODA store UI 01"},{"id":"E-commerce-02","src":"/assets/E-commerce/2.png","alt":"E-commerce website — NODA store UI 02"},{"id":"E-commerce-03","src":"/assets/E-commerce/3.png","alt":"E-commerce website — NODA store UI 03"},{"id":"E-commerce-04","src":"/assets/E-commerce/4.png","alt":"E-commerce website — NODA store UI 04"},{"id":"E-commerce-05","src":"/assets/E-commerce/5.png","alt":"E-commerce website — NODA store UI 05"},{"id":"E-commerce-06","src":"/assets/E-commerce/6.png","alt":"E-commerce website — NODA store UI 06"},{"id":"E-commerce-07","src":"/assets/E-commerce/7.png","alt":"E-commerce website — NODA store UI 07"},{"id":"E-commerce-08","src":"/assets/E-commerce/8.png","alt":"E-commerce website — NODA store UI 08"},{"id":"E-commerce-09","src":"/assets/E-commerce/9.png","alt":"E-commerce website — NODA store UI 09"},{"id":"E-commerce-10","src":"/assets/E-commerce/10.png","alt":"E-commerce website — NODA store UI 10"},{"id":"E-commerce-11","src":"/assets/E-commerce/11.png","alt":"E-commerce website — NODA store UI 11"},{"id":"E-commerce-12","src":"/assets/E-commerce/12.png","alt":"E-commerce website — NODA store UI 12"},{"id":"E-commerce-13","src":"/assets/E-commerce/13.png","alt":"E-commerce website — NODA store UI 13"},{"id":"E-commerce-14","src":"/assets/E-commerce/14.png","alt":"E-commerce website — NODA store UI 14"},{"id":"E-commerce-15","src":"/assets/E-commerce/15.png","alt":"E-commerce website — NODA store UI 15"},{"id":"E-commerce-16","src":"/assets/E-commerce/16.png","alt":"E-commerce website — NODA store UI 16"},{"id":"E-commerce-17","src":"/assets/E-commerce/17.png","alt":"E-commerce website — NODA store UI 17"},{"id":"E-commerce-18","src":"/assets/E-commerce/18.png","alt":"E-commerce website — NODA store UI 18"},{"id":"E-commerce-19","src":"/assets/E-commerce/19.png","alt":"E-commerce website — NODA store UI 19"}]'::jsonb,
    'The business needed an e-commerce website that sells smoothly and an admin dashboard that saves time daily. Operations and sales had to scale.', 'كان المطلوب متجر إلكتروني يبيع بسلاسة مع لوحة تحكم توفر وقت الإدارة اليومي. الهدف هو تشغيل أسهل ونمو في المبيعات.',
    'Built a full e-commerce website: storefront + admin dashboard + database with a clear product structure and an efficient workflow for orders and inventory.', 'تم بناء متجر إلكتروني كامل: واجهة متجر + لوحة تحكم + قاعدة بيانات مع تنظيم المنتجات وسير عمل فعال لإدارة الطلبات والمخزون.',
    'A clearer buying journey, faster admin operations, and a structure that supports SEO pages (categories/products) for long-term traffic.', 'رحلة شراء أوضح، إدارة أسرع، وبنية تدعم صفحات SEO (تصنيفات/منتجات) لزيارات طويلة المدى.',
    'End-to-end build: UX, storefront, dashboard flow, and data structure.', 'تنفيذ كامل: UX، واجهة المتجر، تدفق لوحة التحكم، وبنية البيانات.',
    'Storefront • Admin Dashboard • Database', 'واجهة متجر • لوحة تحكم • قاعدة بيانات',
    '["Map the checkout flow and key pages","Build product/category structure and UI","Implement admin workflow for products and orders","Organize database and data rules","Optimize mobile UX and performance basics","Prepare SEO-ready hierarchy and internal linking"]'::jsonb, '["تحديد مسار الشراء والصفحات الأساسية","تنظيم التصنيفات والمنتجات وبناء الواجهة","تنفيذ لوحة التحكم لإدارة المنتجات والطلبات","تنظيم قاعدة البيانات وقواعد البيانات","تحسين تجربة الموبايل وأساسيات الأداء","تهيئة بنية SEO وروابط داخلية قوية"]'::jsonb,
    '[{"q":{"en":"Is it a full store with admin?","ar":"هل هو متجر كامل مع لوحة تحكم؟"},"a":{"en":"Yes. Storefront, admin dashboard, and database layer are included.","ar":"نعم. يوجد واجهة متجر ولوحة تحكم وقاعدة بيانات."}},{"q":{"en":"Can it support payments and shipping?","ar":"هل يدعم الدفع والشحن؟"},"a":{"en":"Yes, depending on providers. The structure supports adding integrations.","ar":"نعم حسب مزودي الخدمة. الهيكل يدعم إضافة التكاملات."}},{"q":{"en":"Does it help SEO?","ar":"هل يدعم SEO؟"},"a":{"en":"Yes. The hierarchy supports category and product pages with internal links.","ar":"نعم. البنية تدعم صفحات التصنيفات والمنتجات مع روابط داخلية."}}]'::jsonb,
    'Storefront + admin dashboard + database. Clear navigation, fast checkout flows, and SEO-ready structure for categories and products.', 'واجهة متجر + لوحة تحكم + قاعدة بيانات. تصفح واضح، تدفق شراء سريع، وبنية جاهزة لـ SEO للمنتجات والتصنيفات.',
    'Conversion-first UX for buyers, and admin experience that keeps operations simple.', 'تجربة شراء تدفع للتحويل، ولوحة تحكم تجعل الإدارة اليومية أبسط.',
    'Full implementation across UI, dashboard flows, and data structure, with attention to mobile usability and SEO-friendly hierarchy.', 'تنفيذ شامل للواجهة وتجربة لوحة التحكم وبنية البيانات، مع عناية بالموبايل وبنية صفحات تدعم SEO.'
  );
INSERT INTO projects (
    universe, slug, status, featured, 
    name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar,
    focus_keyword_en, focus_keyword_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
    tech_stack, tags, repo_url, live_url, screens,
    case_study_problem_en, case_study_problem_ar, case_study_solution_en, case_study_solution_ar,
    case_study_outcome_en, case_study_outcome_ar, case_study_role_en, case_study_role_ar,
    case_study_stack_en, case_study_stack_ar, case_study_steps_en, case_study_steps_ar,
    faqs,
    highlight_key_points_en, highlight_key_points_ar, highlight_focus_en, highlight_focus_ar,
    highlight_role_en, highlight_role_ar
  ) VALUES (
    9, 'growlik', 'published', true,
    'GrowLik SEO Optimization', 'تحسين SEO لموقع GrowLik',
    'Technical SEO improvements for higher visibility and better snippets.', 'تحسينات SEO تقنية لرفع الظهور وتحسين المقتطفات في نتائج البحث.',
    'A focused SEO engagement: audit + fixes for titles, descriptions, heading structure, internal linking, and schema to improve Google visibility.', 'تعاون SEO مركز: تدقيق ثم إصلاحات للعناوين والوصف وبنية الهيدنجز والروابط الداخلية والسكيما لتحسين الظهور في Google.',
    'SEO optimization', 'تحسين SEO',
    'SEO Optimization: GrowLik Case Study', 'تحسين SEO: دراسة حالة GrowLik',
    'Technical SEO improvements: titles, descriptions, headings, schema, and internal links for clearer snippets and ranking.', 'تحسين SEO تقني: عناوين ووصف وهيدنجز وسكيما وروابط داخلية لتحسين الترتيب والمقتطفات.',
    '["SEO","Technical SEO","Schema"]'::jsonb, '["seo","technical-seo","schema"]'::jsonb, '', '',
    '[{"id":"growlik-01","src":"/assets/growlik/01.png","alt":"SEO optimization — GrowLik page structure 01"},{"id":"growlik-02","src":"/assets/growlik/02.png","alt":"SEO optimization — GrowLik metadata and headings 02"},{"id":"growlik-03","src":"/assets/growlik/03.png","alt":"SEO optimization — GrowLik internal linking 03"},{"id":"growlik-04","src":"/assets/growlik/04.png","alt":"SEO optimization — GrowLik schema and snippet clarity 04"}]'::jsonb,
    'The site needed SEO optimization without redesign: weak titles, unclear headings, and missing schema reduced visibility and snippet quality.', 'الموقع كان يحتاج تحسين SEO بدون إعادة تصميم: عناوين ضعيفة وهيدنجز غير واضح وسكيما غير موجودة مما يضعف الظهور والمقتطفات.',
    'Applied technical SEO: rewrite titles/descriptions, fix H1/H2, strengthen internal links, add schema, and improve image alt context.', 'تم تطبيق SEO تقني: إعادة كتابة title/description، ضبط H1/H2، تقوية الروابط الداخلية، إضافة سكيما، وتحسين alt للصور بسياق واضح.',
    'Cleaner indexing signals, clearer snippets, and a structure ready for scaling content with consistent metadata rules.', 'إشارات فهرسة أوضح، مقتطفات أفضل، وبنية جاهزة للتوسع في المحتوى مع قواعد ميتاداتا ثابتة.',
    'Audit + metadata rewrite + schema + linking plan.', 'تدقيق + إعادة كتابة الميتاداتا + سكيما + خطة روابط داخلية.',
    'Metadata • Headings • Schema • Internal Links', 'ميتا • هيدنجز • سكيما • روابط داخلية',
    '["Audit priority pages","Rewrite title/description","Fix heading hierarchy","Add schema markup","Improve alt text","Strengthen internal links"]'::jsonb, '["مراجعة الصفحات الأهم","إعادة كتابة العنوان والوصف","ضبط الهيدنجز","إضافة السكيما","تحسين alt","تقوية الروابط الداخلية"]'::jsonb,
    '[{"q":{"en":"Was any UI redesigned?","ar":"هل تم تغيير التصميم؟"},"a":{"en":"No. The work focused on SEO structure, metadata, schema, and internal linking only.","ar":"لا. العمل كان على بنية SEO والميتا والسكيما والروابط الداخلية فقط."}},{"q":{"en":"Can the same SEO approach be applied to services pages?","ar":"هل يمكن تطبيق نفس الأسلوب على الخدمات؟"},"a":{"en":"Yes. Services pages benefit from focused keywords, FAQs, and schema with internal linking.","ar":"نعم. صفحات الخدمات تستفيد جدًا من كلمات مفتاحية وFAQ وسكيما وروابط داخلية."}},{"q":{"en":"Does alt text really matter?","ar":"هل alt مهم فعلًا؟"},"a":{"en":"Yes. It improves accessibility and provides image context for search engines.","ar":"نعم. يدعم الوصول ويعطي سياقًا لمحركات البحث."}}]'::jsonb,
    'SEO audit + fixes: titles, meta descriptions, heading hierarchy, and structured data for clearer search snippets.', 'تدقيق SEO ثم إصلاحات: العناوين والوصف وبنية الهيدنجز وإضافة سكيما لرفع جودة المقتطفات في البحث.',
    'Search visibility improvements with cleaner metadata and content structure (Google + AI search).', 'تحسين الظهور في البحث عبر ميتاداتا أوضح وبنية محتوى أنظف (Google + البحث بالذكاء الاصطناعي).',
    'Technical SEO implementation: metadata, headings, internal links, schema markup, and basic performance checks.', 'تنفيذ SEO تقني: ميتاداتا، هيدنجز، روابط داخلية، سكيما، ومراجعة أساسيات الأداء.'
  );

